import{z as o,x as i,o as t,c as d,q as A,j as s,D as n,d as e,s as l,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"符号幅度与反码对照","description":"","frontmatter":{"title":"符号幅度与反码对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sign-magnitude.md","filePath":"cs/sign-magnitude.md","lastUpdated":1791063341000}'),p={name:"cs/sign-magnitude.md"};function m(D,E,u,h,C,F){const r=i("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="符号幅度与反码对照" tabindex="-1">符号幅度与反码对照 <a class="header-anchor" href="#符号幅度与反码对照" aria-label="Permalink to &quot;符号幅度与反码对照&quot;">​</a></h1><div class="epigraph"><p>符号位加幅值最像人写的负数，却逼加法器先看符号；补码把取负做成模 $2^n$ 下加一，才与上一课同一套全加器兼容。</p><footer>—— 据 Knuth, The Art of Computer Programming, Vol. 2；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p>上一课<a href="/cs/twos-complement">补码与溢出</a>钉死了：最高位负权，减法并进模 \\(2^n\\) 加法，溢出按同号和异号读。本课不重推 \\(\\mathrm{val}(x)\\)，也不从「负数公理」另起。缺口是：原码、反码仍然出现在文献和浮点符号里，必须对照<strong>为什么默认丢掉它们</strong>，而不是再发明第四种基。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>人写 \\(-5\\) 是符号加绝对值。原码照搬：最高位 \\(1\\) 表示负，其余位按上一课的无符号幅值读。加法要先比较符号，同号加幅值、异号减幅值，还要处理 \\(+0\\) 与 \\(-0\\)。反码按位取反得负数，两个零仍在，\\(1\\) 的进位必须从最高位绕回最低位（循环进位）。缺口因此不是「要不要符号」，而是：哪一种编码让<strong>已经造好的模 \\(2^n\\) 加法器</strong>继续够用。</p><p>上一课给出的答案是补码。本课只把另外两条路摆在旁边，钉死后课整数默认补码；<a href="/cs/fixed-and-float">定点与浮点</a>里 754 的符号位会再走回原码风格，那是后课的缺口。</p><h3 id="两个零不是「多一个方便」" tabindex="-1">两个零不是「多一个方便」 <a class="header-anchor" href="#两个零不是「多一个方便」" aria-label="Permalink to &quot;两个零不是「多一个方便」&quot;">​</a></h3><p>\\(+0\\) 与 \\(-0\\) 比特不同，比较、哈希、分支都会分叉。补码只有一个零。反码的循环进位是额外数据通路，不是「差不多的加一」。把三种编码当成「都能表示负数，随便选」，后课 ALU 会多出整页例外。</p><p><span class="marginnote">Knuth Vol. 2 §4.1 把符号幅度、反码、补码写成同一位权系统上的三种符号约定。Patterson/Hennessy 直接采用补码，把另外两种留给历史与对照。</span></p><p><span class="marginnote">数字实例：\\(n=4\\)、记 \\(-5\\)——原码是 \\(1101\\)（符号 \\(1\\) 加幅值 \\(101=5\\)），反码是 \\(1010\\)（\\(0101\\) 逐位取反），补码是 \\(1011\\)（取反再加 \\(1\\)）。三份比特都「表示负数」，但只有 \\(1011\\) 能直接和无符号加法器一起算 \\(-5+5=0000\\)。</span></p><p><span class="marginnote">初学者容易以为反码的「按位取反」和补码的「取反加一」只差琐碎一步、随便用哪个都行。实际上差的那一加法决定了整条数据通路：反码最高位溢出必须绕回最低位（循环进位），补码则直接丢进模 \\(2^n\\) 加法、什么都不用绕。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定宽度 \\(n\\)。原码：\\(\\mathrm{val}=(-1)^s\\cdot m\\)，幅值 \\(m\\) 用 \\(n-1\\) 位无符号。反码：负数是正数按位取反，数值上相当于模 \\(2^n-1\\)。补码：取反再加一，即上一课的模 \\(2^n\\)。三种都用 \\(n\\) 比特，可表示的整数集合略有不同：原码、反码对称但浪费一个码字给第二份零；补码范围不对称，多一个最负值。</p>',13)),(t(),s(B,null,{default:n(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SM%5B%22%E5%8E%9F%E7%A0%81%EF%BC%9A%E7%AC%A6%E5%8F%B7%E5%8A%A0%E5%B9%85%E5%80%BC%22%5D%20--%3E%20ADD1%5B%22%E5%8A%A0%E5%87%8F%E5%88%86%E8%B7%AF%22%5D%0A%20%20OC%5B%22%E5%8F%8D%E7%A0%81%EF%BC%9A%E5%8F%96%E5%8F%8D%22%5D%20--%3E%20ENDA%5B%22%E5%BE%AA%E7%8E%AF%E8%BF%9B%E4%BD%8D%22%5D%0A%20%20TC%5B%22%E8%A1%A5%E7%A0%81%EF%BC%9A%E5%8F%96%E5%8F%8D%E5%8A%A0%E4%B8%80%22%5D%20--%3E%20ALU%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E6%A8%A1%202%5En%20%E5%8A%A0%E6%B3%95%22%5D%0A%20%20ALU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AE%9A%E7%82%B9%E4%BB%8D%E9%BB%98%E8%AE%A4%E8%A1%A5%E7%A0%81%22%5D%0A"})]),fallback:n(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"硬件对照到此为止。本课不把浮点的符号–幅度乘指数提前展开。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("选补码之后，寄存器里的有符号字与无符号字共享加法器，区别只在溢出与比较的读法——上一课已经分开 "),a("code",null,"blt"),e(" 与 "),a("code",null,"bltu"),e("。原码仍出现在：人读的打印、以及后课 IEEE 754 的符号位。那不是整数 ALU 改回原码，而是另一套编码。混用「最高位是符号」而不说是哪一种，符号扩展会做错。")],-1)),E[6]||(E[6]=a("p",null,"同一个 \\(-5+5\\)，三种编码各自要走的加法路径不同——这正是「为什么默认补码」的直观答案：",-1)),(t(),s(B,null,{default:n(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%AE%97%20x%20%2B%20(-x)%22%5D%20--%3E%20P1%5B%22%E5%8E%9F%E7%A0%81%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Q%20--%3E%20P2%5B%22%E5%8F%8D%E7%A0%81%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Q%20--%3E%20P3%5B%22%E8%A1%A5%E7%A0%81%E8%B7%AF%E5%BE%84%22%5D%0A%20%20P1%20--%3E%20A1%5B%22%E5%85%88%E6%AF%94%E7%AC%A6%E5%8F%B7%E5%86%8D%E6%AF%94%E5%B9%85%E5%80%BC%3Cbr%3E%E5%90%8C%E5%B9%85%E5%BC%82%E5%8F%B7%EF%BC%9A%E7%9B%B4%E6%8E%A5%E5%BE%97%200%3Cbr%3E%E4%BD%86%E8%A6%81%E7%89%B9%E5%88%A4%20%2B0%20%E4%B8%8E%20-0%22%5D%0A%20%20P2%20--%3E%20A2%5B%22%E6%99%AE%E9%80%9A%E5%8A%A0%E6%B3%95%E5%90%8E%E5%8F%91%E7%8E%B0%3Cbr%3E%E6%9C%80%E9%AB%98%E4%BD%8D%E6%9C%89%E8%BF%9B%E4%BD%8D%3Cbr%3E%E5%BF%85%E9%A1%BB%E6%8A%8A%E8%BF%9B%E4%BD%8D%E7%BB%95%E5%9B%9E%E6%9C%80%E4%BD%8E%E4%BD%8D%22%5D%0A%20%20P3%20--%3E%20A3%5B%22%E7%9B%B4%E6%8E%A5%E9%80%81%E8%BF%9B%E6%A8%A1%202%5En%20%E5%8A%A0%E6%B3%95%E5%99%A8%3Cbr%3E%E7%BB%93%E6%9E%9C%200000%20%E4%B8%80%E6%AC%A1%E5%88%B0%E4%BD%8D%22%5D%0A"})]),fallback:n(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p>这一步如果做错了，后面会连锁出错：比如把原码数据当补码读，\\(1101\\)（原码 \\(-5\\)）会被读成 \\(-3\\)；做哈希或集合去重时，\\(+0\\) 与 \\(-0\\) 又会变成两个不同的键。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入饱和算术、不讨论符号–幅度的乘法比补码更省的说法是否值得为加法分路买单。也不把 Gray 码的相邻性套到符号上：负数编码是数值约定，不是枚举次序。</p><p>后课默认：有符号整数是补码；谈到原码，只作为对照或浮点符号，不再当整数加法的默认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原码像书写法，加法要分符号，且有两个零。</li><li>反码要循环进位；补码与模 \\(2^n\\) 加法兼容。</li><li>后课整数默认补码；754 符号是另一套原码风格。</li><li>出处：Knuth, TAOCP Vol. 2；Patterson and Hennessy, COD。</li></ul>',6))])}const g=o(p,[["render",m]]);export{c as __pageData,g as default};
